async function dashboardMeta(){await primeOperations().catch(()=>{});return{locations:state.cache.locations||[],centers:state.cache.costCenters||[],suppliers:(state.cache.suppliers||[]).filter(item=>item.active!==false),categories:(state.cache.categories||[]).filter(item=>item.active!==false)}}
function dashboardOption(items,value='',label='Todos'){return`<option value="">${label}</option>${items.map(item=>`<option value="${esc(item.id)}" ${String(item.id)===String(value)?'selected':''}>${esc(item.name)}</option>`).join('')}`}
function curvePath(points){if(!points.length)return'';if(points.length===1)return`M ${points[0].x} ${points[0].y}`;let d=`M ${points[0].x} ${points[0].y}`;for(let i=0;i<points.length-1;i++){const a=points[i],b=points[i+1],mid=(a.x+b.x)/2;d+=` C ${mid} ${a.y}, ${mid} ${b.y}, ${b.x} ${b.y}`}return d}
function chartCurve(monthly){const width=760,height=220,pad=28,actual=monthly.map(item=>Number(item.spend||0)),estimated=monthly.map(item=>Number(item.estimatedSpend||0)),max=Math.max(1,...actual,...estimated),points=values=>values.map((value,index)=>({x:values.length===1?width/2:pad+index*(width-pad*2)/(values.length-1),y:height-pad-value/max*(height-pad*2),value})),a=points(actual),e=points(estimated),area=a.length?`${curvePath(a)} L ${a.at(-1).x} ${height-pad} L ${a[0].x} ${height-pad} Z`:'';return`<div class="v43-chart-legend"><span><i></i>Facturado recibido</span><span><i></i>Valorización esperada</span></div><svg class="v43-chart" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Evolución de compras recibidas">${[.25,.5,.75,1].map(step=>`<line class="v43-grid-line" x1="${pad}" x2="${width-pad}" y1="${height-pad-step*(height-pad*2)}" y2="${height-pad-step*(height-pad*2)}"/>`).join('')}${area?`<path class="v43-area" d="${area}"/>`:''}<path class="v43-line-estimate" d="${curvePath(e)}"/><path class="v43-line-actual" d="${curvePath(a)}"/>${a.map(point=>`<circle class="v43-dot" cx="${point.x}" cy="${point.y}" r="4"><title>${money(point.value)}</title></circle>`).join('')}</svg><div class="v43-chart-labels" style="--n:${Math.max(1,monthly.length)}">${monthly.map(item=>`<span>${esc(new Date(`${item.month}-01T12:00:00`).toLocaleDateString('es-CL',{month:'short'}))}</span>`).join('')}</div>`}
function spendBars(items){const list=(items||[]).slice(0,7),max=Math.max(1,...list.map(item=>Number(item.spend||item.estimatedSpend||0)));return`<div class="v43-bars">${list.map(item=>{const value=Number(item.spend||item.estimatedSpend||0);return`<div class="v43-bar"><span>${esc(item.name||item.category||item.costCenterName||'Sin nombre')}</span><span class="v43-bar-track"><i style="width:${Math.max(2,value/max*100)}%"></i></span><strong>${money(value)}</strong></div>`}).join('')||'<div class="v43-inline-note">Sin datos para este período.</div>'}</div>`}
function metricCard(label,value,note,trend=''){return`<article class="v43-kpi"><span>${esc(label)}</span><strong class="${trend}">${value}</strong><small>${esc(note)}</small></article>`}
function renderDashboardAnalytics(analytics,{stale=false}={}){const target=$('#v43DashboardBody');if(!target)return;const m=analytics.metrics||{},variation=Number(m.variationVsPrevious||0),variationPct=Math.round(variation*1000)/10;target.innerHTML=`${stale?'<div class="v43-dashboard-stale">Mostrando los últimos datos disponibles mientras se recupera la conexión.</div>':''}<section class="v43-kpis">${metricCard('Gasto recibido',money(m.spend||m.estimatedSpend||0),`${Number(m.invoices||0)} documentos`)}${metricCard('Variación',`${variationPct>0?'+':''}${variationPct}%`,'vs. período anterior',variationPct>0?'negative':variationPct<0?'positive':'')}${metricCard('Recepciones',String(Number(m.receptions||0)),`${Number(m.orders||0)} pedidos`)}${metricCard('Proveedores',String(Number(m.suppliers||0)),'usados en el período')}${metricCard('Pagos vencidos',money(m.overdueAmount||0),`${Number(m.overduePayments||0)} documentos`,Number(m.overdueAmount||0)>0?'negative':'')}${metricCard('Diferencias',String(Number(m.openIssues||0)),`${Number(m.rejectedQuantity||0)} unidades rechazadas`,Number(m.openIssues||0)>0?'negative':'')}</section><section class="v43-dashboard-grid"><article class="v43-panel full"><div class="v43-panel-head"><div><h3>Evolución y comparación</h3><p>Curva mensual por fecha real de recepción: facturado versus valorización esperada.</p></div></div>${chartCurve(analytics.monthly||[])}</article><article class="v43-panel"><div class="v43-panel-head"><div><h3>Costos por centro de costo</h3><p>Participación del gasto recibido.</p></div></div>${spendBars(analytics.costCenterSpend||[])}</article><article class="v43-panel"><div class="v43-panel-head"><div><h3>Costos por categoría</h3><p>Qué familias concentran el gasto.</p></div></div>${spendBars(analytics.categorySpend||[])}</article><article class="v43-panel"><div class="v43-panel-head"><div><h3>Principales proveedores</h3><p>Ranking según compras recibidas.</p></div></div>${spendBars(analytics.topSuppliers||[])}</article><article class="v43-panel"><div class="v43-panel-head"><div><h3>Presupuestos por centro</h3><p>Uso contra presupuesto configurado.</p></div></div><div class="v43-bars">${(analytics.budgets||[]).slice(0,7).map(item=>`<div class="v43-bar"><span>${esc(item.costCenterName)}</span><span class="v43-bar-track"><i style="width:${clamp(Number(item.usagePct||0)*100,2,100)}%"></i></span><strong>${Math.round(Number(item.usagePct||0)*100)}%</strong></div>`).join('')||'<div class="v43-inline-note">Configura presupuestos para comparar ejecución.</div>'}</div></article></section>`}
function dashboardQuery(){const params=new URLSearchParams();for(const[id,key]of [['v43From','from'],['v43To','to'],['v43Location','locationId'],['v43Center','costCenterId'],['v43Supplier','supplierId'],['v43Category','categoryId']]){const value=$(`#${id}`)?.value;if(value)params.set(key,value)}return params}
async function loadDashboardV43(){const target=$('#v43DashboardBody');if(!target)return;target.innerHTML='<div class="v43-loading-card"><div><h3>Actualizando indicadores</h3><p>Consultando recepciones, facturas y centros de costo.</p></div></div>';const query=dashboardQuery(),key=query.toString();try{const payload=await api(`/api/dashboard/analytics-v41?${key}`,{fresh:true,timeout:45000}),analytics=payload.analytics;sessionStorage.setItem('nuvasto:v43:dashboard-cache',JSON.stringify({key,analytics,at:Date.now()}));sessionStorage.setItem('nuvasto:v43:dashboard-filters',JSON.stringify(Object.fromEntries(query)));renderDashboardAnalytics(analytics)}catch(error){let cached=null;try{cached=JSON.parse(sessionStorage.getItem('nuvasto:v43:dashboard-cache')||'null')}catch{}if(cached?.analytics)renderDashboardAnalytics(cached.analytics,{stale:true});else target.innerHTML=`<div class="v43-loading-card"><div><h3>No se pudieron cargar los indicadores</h3><p>${esc(error.message)}</p><button class="btn primary" id="v43RetryDashboard">Reintentar</button></div></div>`;$('#v43RetryDashboard')?.addEventListener('click',loadDashboardV43)}}
function setDashboardPeriod(days){const to=new Date(),from=new Date();from.setDate(to.getDate()-days+1);$('#v43From').value=from.toISOString().slice(0,10);$('#v43To').value=to.toISOString().slice(0,10);$$('[data-v43-period]').forEach(button=>button.classList.toggle('active',Number(button.dataset.v43Period)===days));loadDashboardV43()}
async function renderDashboardV43(){state.view='dashboard';state.subview='';$$('.nav-item[data-view],.bottom-item[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view==='dashboard'));if($('#pageEyebrow'))$('#pageEyebrow').textContent='CONTROL DE GESTIÓN';if($('#pageTitle'))$('#pageTitle').textContent='Inicio';const meta=await dashboardMeta(),saved=JSON.parse(sessionStorage.getItem('nuvasto:v43:dashboard-filters')||'{}');$('#mainContent').innerHTML=`<section class="v43-dashboard"><header class="v43-dashboard-head"><div><span class="eyebrow">COMPRAS Y ABASTECIMIENTO</span><h2>Centro de control</h2><p>${esc(state.me?.organization?.name||'Nuvasto')} · costos, recepción y variaciones en una sola vista.</p></div><div class="v43-dashboard-actions"><button class="btn" id="v43PrintDashboard">PDF / imprimir</button><button class="btn primary" data-action="new-order">＋ Pedido</button></div></header><div class="v43-periods"><button class="btn small" type="button" data-v43-period="30">30 días</button><button class="btn small" type="button" data-v43-period="90">3 meses</button><button class="btn small active" type="button" data-v43-period="183">6 meses</button><button class="btn small" type="button" data-v43-period="365">12 meses</button></div><details class="v43-filter-panel"><summary><span>Filtros de análisis</span><span>Local · centro · proveedor · categoría</span></summary><div class="v43-filter-grid"><label><span>Desde</span><input id="v43From" type="date" value="${esc(saved.from||'')}"></label><label><span>Hasta</span><input id="v43To" type="date" value="${esc(saved.to||'')}"></label><label><span>Local</span><select id="v43Location">${dashboardOption(meta.locations,saved.locationId,'Todos')}</select></label><label><span>Centro</span><select id="v43Center">${dashboardOption(meta.centers,saved.costCenterId,'Todos')}</select></label><label><span>Proveedor</span><select id="v43Supplier">${dashboardOption(meta.suppliers,saved.supplierId,'Todos')}</select></label><label><span>Categoría</span><select id="v43Category">${dashboardOption(meta.categories,saved.categoryId,'Todas')}</select></label><div class="actions"><button class="btn primary" id="v43ApplyDashboard" type="button">Aplicar</button><button class="btn" id="v43ClearDashboard" type="button">Limpiar</button></div></div></details><div id="v43DashboardBody"></div></section>`;$('#v43PrintDashboard').onclick=()=>window.print();$('#v43ApplyDashboard').onclick=loadDashboardV43;$('#v43ClearDashboard').onclick=()=>{for(const id of ['v43From','v43To','v43Location','v43Center','v43Supplier','v43Category'])$(`#${id}`).value='';$$('[data-v43-period]').forEach(button=>button.classList.remove('active'));loadDashboardV43()};$$('[data-v43-period]').forEach(button=>button.onclick=()=>setDashboardPeriod(Number(button.dataset.v43Period)));if(!saved.from&&!saved.to)setDashboardPeriod(183);else loadDashboardV43()}

function closeContext(){document.querySelector('.v43-context-backdrop')?.remove();document.querySelector('.v43-context-menu')?.remove()}
async function orderForMenu(id){try{const payload=await api('/api/orders/advanced',{ttl:15000,timeout:25000});return(payload.orders||[]).find(item=>item.id===id)}catch{const payload=await api('/api/orders',{ttl:15000,timeout:25000});return(payload.orders||[]).find(item=>item.id===id)}}
async function openOrderContext(id,anchor){closeContext();const order=await orderForMenu(id)||{id,status:'requested',supplierName:'Pedido'},draft=order.status==='draft',received=['received','reconciled','closed'].includes(order.status),actions=draft?[['view','Ver pedido','Abrir el detalle completo','↗'],['edit','Editar','Modificar cantidades y entrega','✎'],['emit','Emitir','Asignar folio y generar PDF','✓'],['duplicate','Duplicar','Crear otro borrador','⧉']]:[['view','Ver pedido','Abrir el detalle completo','↗'],['documents','Documentos','Facturas y documentos sin cargo','▧'],[received?'reconcile':'receive',received?'Conciliar':'Registrar recepción',received?'Comparar pedido, recepción y factura':'Registrar lo que llegó','✓'],['share','Compartir PDF','Abrir menú de compartir','⇧']];const backdrop=document.createElement('div');backdrop.className='v43-context-backdrop';const menu=document.createElement('section');menu.className='v43-context-menu';menu.innerHTML=`<div class="v43-context-head"><strong>${esc(order.supplierName||'Pedido')}</strong><small>${esc(order.folio||'')}</small></div><div class="v43-context-actions">${actions.map(([key,label,help,icon])=>`<button class="v43-context-action" type="button" data-v43-context="${key}"><i>${icon}</i><span><strong>${label}</strong><small>${help}</small></span></button>`).join('')}</div>`;document.body.append(backdrop,menu);const rect=anchor.getBoundingClientRect(),width=Math.min(300,window.innerWidth-28),left=clamp(rect.right-width,10,window.innerWidth-width-10),estimated=Math.min(330,58+actions.length*55),top=rect.bottom+8+estimated<window.innerHeight?rect.bottom+8:Math.max(10,rect.top-estimated-8);menu.style.left=`${left}px`;menu.style.top=`${top}px`;backdrop.onclick=closeContext;menu.querySelectorAll('[data-v43-context]').forEach(button=>button.onclick=async()=>{const action=button.dataset.v43Context;closeContext();if(action==='view')return openOrderDetail(id);if(['edit','emit','duplicate','receive','reconcile'].includes(action)){await openOrderDetail(id);const selector={edit:'#v30EditOrder',emit:'#v30EmitOrder',duplicate:'#v30Duplicate',receive:'#v30Reception',reconcile:'#v30Reconcile'}[action];return setTimeout(()=>$(selector)?.click(),70)}if(action==='documents')return window.NuvastoMultiInvoice?.open({orderId:id,returnToHistory:true});if(action==='share'){try{const document=await ensureOrderDocument(order);await shareDocument(document.key,document.name)}catch(error){toast(error.message,'error')}}})}
function enhanceHistoryMenus(){for(const button of $$('[data-v32-order-open]')){if(button.dataset.v43Prepared)return;const id=button.dataset.v32OrderOpen,clone=button.cloneNode(true);clone.removeAttribute('data-v32-order-open');clone.dataset.v43Prepared='1';clone.dataset.v43OrderMenu=id;clone.setAttribute('aria-label','Más acciones');clone.onclick=event=>{event.preventDefault();event.stopPropagation();openOrderContext(id,clone).catch(error=>toast(error.message,'error'))};button.replaceWith(clone)}}

function fixHeader(){if($('#v41Bell'))$('#v40Notifications')?.remove();const actions=$('.top-actions');if(actions&&$('#v41Bell')&&actions.firstElementChild!==$('#v41Bell'))actions.insertBefore($('#v41Bell'),actions.firstChild)}
function navItem(view,label,help,icon){return`<button class="v43-more-item" type="button" data-v43-go="${view}"><i>${icon}</i><span><strong>${label}</strong><small>${help}</small></span><b>›</b></button>`}
function openMoreMenu(anchor){document.querySelector('.v43-more-backdrop')?.remove();document.querySelector('.v43-more-sheet')?.remove();const role=state.me?.user?.role||'readonly',admin=['owner','admin'].includes(role),canBuy=['owner','admin','purchaser','approver'].includes(role),backdrop=document.createElement('div'),sheet=document.createElement('section');backdrop.className='v43-more-backdrop';sheet.className='v43-more-sheet';sheet.innerHTML=`<div class="v43-more-group"><span>Compras y abastecimiento</span>${navItem('orders','Pedidos','Creación, emisión y documentos','▤')}${navItem('receiving','Recepción','Control de lo que llegó','✓')}${navItem('history','Historial','Trazabilidad por folio','◷')}</div><div class="v43-more-group"><span>Gestión</span>${navItem('finance','Finanzas','Pagos, vencimientos y proveedores','$')}${navItem('approvals','Aprobaciones','Pendientes por autorizar','◇')}</div><div class="v43-more-group"><span>Datos maestros</span>${navItem('catalog','Productos','Catálogo y relaciones','◫')}${canBuy?navItem('operations','Operaciones','Categorías, centros y recorridos','◎'):''}${navItem('suppliers','Proveedores','Condiciones e identidad','◇')}</div><div class="v43-more-group"><span>Administración</span>${navItem('settings','Configuración','Empresa, políticas y apariencia','⚙')}${admin?navItem('team','Usuarios','Roles y accesos','◎'):''}${admin?navItem('audit','Auditoría','Cambios y trazabilidad','◴'):''}</div>`;document.body.append(backdrop,sheet);backdrop.onclick=()=>{backdrop.remove();sheet.remove()};sheet.querySelectorAll('[data-v43-go]').forEach(button=>button.onclick=()=>{backdrop.remove();sheet.remove();openRoute(button.dataset.v43Go,button.dataset.v43Go==='operations'?'home':'').catch(error=>toast(error.message,'error'))})}
function organizeNavigation(){const nav=$('.side-nav[aria-label="Navegación principal"]');if(nav&&!nav.dataset.v43){nav.dataset.v43='1';if(!nav.querySelector('[data-view="operations"]')){const button=document.createElement('button');button.className='nav-item';button.dataset.view='operations';button.innerHTML='<span class="nav-icon">◎</span><span>Operaciones</span>';nav.append(button)}const groups=[['COMPRAS Y ABASTECIMIENTO',['dashboard','orders','receiving','history']],['GESTIÓN',['invoices','finance','approvals']],['DATOS MAESTROS',['catalog','suppliers','operations']]];for(const[label,views]of groups){const marker=document.createElement('span');marker.className='v43-nav-section';marker.textContent=label;nav.append(marker);for(const view of views){const item=nav.querySelector(`[data-view="${view}"]`);if(item)nav.append(item)}}}
  const bottom=$('.bottom-nav');if(!bottom)return;const role=state.me?.user?.role||'readonly',second=bottom.querySelector('.bottom-item:nth-of-type(2)');if(second&&!second.dataset.v43Role){second.dataset.v43Role='1';const target=role==='receiver'?'receiving':role==='finance'?'finance':role==='approver'?'approvals':role==='readonly'?'history':'orders',labels={orders:['▤','Pedidos'],receiving:['✓','Recepción'],finance:['$','Finanzas'],approvals:['◇','Aprobar'],history:['◷','Historial']};second.dataset.view=target;second.innerHTML=`<span>${labels[target][0]}</span><small>${labels[target][1]}</small>`}
  let more=bottom.querySelector('.bottom-item[data-view="settings"],.bottom-item[data-v43-more]');if(more&&!more.dataset.v43More){const clone=more.cloneNode(true);clone.removeAttribute('data-view');clone.dataset.v43More='1';clone.innerHTML='<span>☰</span><small>Más</small>';clone.onclick=event=>{event.preventDefault();event.stopPropagation();openMoreMenu(clone)};more.replaceWith(clone)}}

function startLoadingWatch(){clearTimeout(watchTimer);const root=$('#mainContent');if(!root)return;const text=root.textContent||'';if(!/Cargando información|Cargando indicadores|Actualizando indicadores/i.test(text))return;const view=state.view,subview=state.subview;watchTimer=setTimeout(()=>{const current=$('#mainContent');if(!current||state.view!==view||state.subview!==subview||!/Cargando información|Cargando indicadores/i.test(current.textContent||''))return;current.innerHTML=`<div class="v43-loading-card"><div><h3>La sección está tardando más de lo normal</h3><p>La sesión sigue activa. Puedes reintentar sin salir de Nuvasto.</p><button class="btn primary" id="v43RetryView">Reintentar</button></div></div>`;$('#v43RetryView').onclick=()=>openRoute(view,subview||'',{replace:true}).catch(error=>toast(error.message,'error'))},12000)}

function enhanceAll(){fixHeader();organizeNavigation();enhanceHistoryMenus();enhanceProcurementConfiguration().catch(error=>console.warn('v43_proc_enhance_failed',error));if($('#modalTitle')?.textContent.trim()==='Lista maestra')applyFreshMasterOrdering().catch(()=>{});if(state.view==='settings'){ensurePolicyAnchor();renderPolicySection().catch(()=>{})}startLoadingWatch()}
function scheduleEnhance(){if(enhanceQueued)return;enhanceQueued=true;requestAnimationFrame(()=>{enhanceQueued=false;enhanceAll()})}

export function initializeExperienceV43(){
  if(initialized)return;initialized=true;injectStyles();registerRouteRenderer('dashboard',renderDashboardV43);registerRouteRenderer('operations',renderOperationsV43);window.addEventListener('pedidos:view-rendered',event=>{if(event.detail?.view==='settings')ensurePolicyAnchor();scheduleEnhance()});window.addEventListener('nuvasto:v43-ordering-changed',()=>{orderingCache.clear();applyFreshMasterOrdering().catch(()=>{})});new MutationObserver(records=>{if(records.some(record=>record.addedNodes.length)){if(state.view==='settings')ensurePolicyAnchor();scheduleEnhance()}}).observe(document.body,{subtree:true,childList:true});setTimeout(()=>{if(state.token)primeOperations().catch(()=>{});scheduleEnhance()},500);window.NuvastoExperienceV43=Object.freeze({version:VERSION,primeOperations,renderDashboardV43})
}
